cat > src/types.ts <<'EOF'
import { z } from 'zod';

export const CLASSIFICATIONS = ['product_bug', 'flaky_test', 'environment_issue', 'test_gap'] as const;
export const EVIDENCE_SOURCES = ['log', 'diff', 'history', 'signal', 'known_defect'] as const;
export const ACTION_TYPES = ['file_bug', 'quarantine', 'fix_test', 'rerun', 'restart_env', 'escalate_human'] as const;

const Classification = z.enum(CLASSIFICATIONS);

export const TriageResultSchema = z.object({
  classification: Classification,
  confidence: z.enum(['high', 'medium', 'low']),
  summary: z.string().describe('One or two sentences: what failed and why you believe that.'),
  evidence: z
    .array(
      z.object({
        source: z.enum(EVIDENCE_SOURCES),
        quote: z.string().describe('Exact text copied from the input (log, diff or signal). Never paraphrase.'),
        why: z.string().describe('What this quote tells you about the cause.'),
      }),
    )
    .min(1),
  alternative: z.object({
    classification: Classification,
    why_not: z.string().describe('Why the runner-up classification was rejected.'),
  }),
  known_defect: z.string().nullable().describe('DEF-xx id from the defect log if this matches one, else null.'),
  next_action: z.object({
    type: z.enum(ACTION_TYPES),
    detail: z.string(),
    owner_pod: z.enum(['Checkout & Payments', 'Catalogue & Pricing', 'Storefront', 'Quality Platform']),
  }),
  needs_human: z.boolean(),
});

export type TriageResult = z.infer<typeof TriageResultSchema>;
export type Classification = (typeof CLASSIFICATIONS)[number];

/** What the caller provides. Everything else is gathered by the evidence collector. */
export interface TriageInput {
  testName: string;
  log: string;
  gitDiff: string;
}

/** Optional context the collector adds from CI artifacts. */
export interface RunContext {
  file?: string;
  project?: string;
  status?: string; // Playwright: expected | unexpected | flaky | skipped
  retries?: number;
  attempts?: { status: string; error?: string }[];
  annotations?: { type: string; description?: string }[];
  siblingFailures: string[];
  totalFailed?: number;
  totalExecuted?: number;
  unhealthyContainers: string[];
  testCaseId?: string;
}

export interface Signal {
  id: string;
  hint: string;
  quote: string;
}

export interface EvidencePack {
  input: TriageInput;
  context: RunContext;
  signals: Signal[];
}
EOF
cat > src/llm/LlmClient.ts <<'EOF'
export interface LlmRequest {
  system: string;
  prompt: string;
  /** JSON Schema the reply must satisfy. */
  jsonSchema: object;
}

export interface LlmResponse {
  /** Parsed structured output, not yet validated by our own schema. */
  output: unknown;
  durationMs: number;
  costUsd?: number;
  model?: string;
}

export interface LlmClient {
  complete(req: LlmRequest): Promise<LlmResponse>;
}
EOF
cat > src/llm/ClaudeCodeCli.ts <<'EOF'
import { spawn } from 'node:child_process';
import type { LlmClient, LlmRequest, LlmResponse } from './LlmClient.ts';

export interface ClaudeCodeOptions {
  model?: string; // alias such as "sonnet" or "opus"
  timeoutMs?: number;
  bin?: string;
}

/**
 * Runs the model through the user's own Claude Code login (`claude -p`), so no API key is involved.
 *
 * - `--tools ""`: the model gets no Bash/Read; it only reasons over the evidence in the prompt.
 * - `--setting-sources ""` and `--no-session-persistence`: the user's hooks, CLAUDE.md and memory
 *   stay out of the classification and nothing is saved to session history.
 * - Not `--bare`: bare mode accepts only an API key.
 * - ANTHROPIC_API_KEY is removed from the child's environment so the CLI cannot fall back to it.
 */
export class ClaudeCodeCli implements LlmClient {
  constructor(private readonly opts: ClaudeCodeOptions = {}) {}

  complete(req: LlmRequest): Promise<LlmResponse> {
    const args = [
      '-p',
      '--tools', '',
      '--output-format', 'json',
      '--json-schema', JSON.stringify(req.jsonSchema),
      '--system-prompt', req.system,
      '--no-session-persistence',
      '--setting-sources', '',
    ];
    if (this.opts.model) args.push('--model', this.opts.model);

    const env = { ...process.env };
    delete env.ANTHROPIC_API_KEY;
    delete env.ANTHROPIC_AUTH_TOKEN;

    const started = Date.now();
    return new Promise((resolve, reject) => {
      const child = spawn(this.opts.bin ?? 'claude', args, { env, stdio: ['pipe', 'pipe', 'pipe'] });
      let stdout = '';
      let stderr = '';
      const timer = setTimeout(() => {
        child.kill('SIGKILL');
        reject(new Error(`claude -p timed out after ${this.opts.timeoutMs ?? 180_000} ms`));
      }, this.opts.timeoutMs ?? 180_000);

      child.stdout.on('data', d => (stdout += d));
      child.stderr.on('data', d => (stderr += d));
      child.on('error', e => {
        clearTimeout(timer);
        reject(e);
      });
      child.on('close', code => {
        clearTimeout(timer);
        if (code !== 0) return reject(new Error(`claude -p exited ${code}: ${stderr || stdout}`.slice(0, 2000)));
        try {
          resolve(parseCliOutput(stdout, Date.now() - started));
        } catch (e) {
          reject(e);
        }
      });
      child.stdin.end(req.prompt);
    });
  }
}

/** Exported for unit tests. Accepts the `--output-format json` envelope. */
export function parseCliOutput(stdout: string, durationMs: number): LlmResponse {
  const envelope = JSON.parse(stdout);
  const env = Array.isArray(envelope) ? envelope.find(e => e.type === 'result') : envelope;
  if (!env) throw new Error('No result in claude output');
  if (env.is_error) throw new Error(`claude reported an error: ${String(env.result).slice(0, 500)}`);

  let output: unknown = env.structured_output;
  if (output === undefined && typeof env.result === 'string') {
    const text = env.result.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
    output = JSON.parse(text);
  }
  if (output === undefined) throw new Error('claude output had neither structured_output nor a JSON result');

  return { output, durationMs, costUsd: env.total_cost_usd, model: env.model };
}
EOF
