1	import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
2	import { join, resolve } from 'node:path';
3	import { parseArgs } from 'node:util';
4	import { fileURLToPath } from 'node:url';
5	import { ClaudeCodeCli } from '../src/llm/ClaudeCodeCli.ts';
6	import { PROMPT_VERSION } from '../src/prompt.ts';
7	import { triage } from '../src/triage.ts';
8	import { CLASSIFICATIONS, type Classification, type RunContext, type TriageResult } from '../src/types.ts';
9	
10	const here = fileURLToPath(new URL('.', import.meta.url));
11	const repoRoot = join(here, '../../');
12	const casesDir = join(here, 'cases');
13	const { values } = parseArgs({
14	  options: {
15	    only: { type: 'string' },
16	    model: { type: 'string', default: 'sonnet' },
17	    force: { type: 'boolean', default: false },
18	    runs: { type: 'string', default: '1' },
19	    out: { type: 'string' },
20	  },
21	});
22	
23	const resultsDir = values.out ? resolve(values.out) : join(here, 'results');
24	const cacheDir = join(resultsDir, 'cache');
25	
26	
27	interface CaseMeta {
28	  id: string;
29	  category: string;
30	  provenance: string;
31	  testName: string;
32	  expected: { classification: Classification; known_defect?: string };
33	  context?: Partial<RunContext>;
34	}
35	
36	interface Run {
37	  result: TriageResult;
38	  guardrailNotes: string[];
39	  durationMs: number;
40	  costUsd?: number;
41	}
42	
43	const only = values.only?.split(',');
44	const ids = readdirSync(casesDir).filter(d => existsSync(join(casesDir, d, 'case.json')) && (!only || only.includes(d)));
45	const runsPer = Number(values.runs);
46	mkdirSync(cacheDir, { recursive: true });
47	
48	const llm = new ClaudeCodeCli({ model: values.model });
49	const rows: { meta: CaseMeta; runs: Run[]; cached: number }[] = [];
50	
51	for (const id of ids) {
52	  const dir = join(casesDir, id);
53	  const meta: CaseMeta = JSON.parse(readFileSync(join(dir, 'case.json'), 'utf8'));
54	  const log = readFileSync(join(dir, 'log.txt'), 'utf8');
55	  const diff = readFileSync(join(dir, 'diff.patch'), 'utf8');
56	  const runs: Run[] = [];
57	  let cached = 0;
58	  for (let i = 0; i < runsPer; i++) {
59	    const cacheFile = join(cacheDir, `${id}.${PROMPT_VERSION}.${values.model}.${i}.json`);
60	    if (!values.force && existsSync(cacheFile)) {
61	      runs.push(JSON.parse(readFileSync(cacheFile, 'utf8')));
62	      cached++;
63	      continue;
64	    }
65	    process.stdout.write(`running ${id} #${i + 1} ... `);
66	    const o = await triage({ testName: meta.testName, log, gitDiff: diff }, llm, repoRoot, { context: meta.context });
67	    const run: Run = { result: o.result, guardrailNotes: o.guardrailNotes, durationMs: o.durationMs, costUsd: o.costUsd };
68	    writeFileSync(cacheFile, JSON.stringify(run, null, 2));
69	    runs.push(run);
70	    console.log(`${run.result.classification} (${run.result.confidence}) in ${(run.durationMs / 1000).toFixed(1)}s`);
71	  }
72	  rows.push({ meta, runs, cached });
73	}
74	
75	// ---------- scoring (first run of each case is the headline; extra runs measure stability) ----------
76	const head = rows.map(r => ({ ...r, got: r.runs[0].result, ok: r.runs[0].result.classification === r.meta.expected.classification }));
77	const correct = head.filter(h => h.ok).length;
78	const pct = (n: number, d: number) => (d ? `${((100 * n) / d).toFixed(0)}%` : 'n/a');
79	
80	const matrix: Record<string, Record<string, number>> = {};
81	for (const c of CLASSIFICATIONS) matrix[c] = Object.fromEntries(CLASSIFICATIONS.map(x => [x, 0]));
