import { readFileSync, writeFileSync } from 'node:fs';
const red = s => s
  .replace(/\/Users\/vipulbhargava/g, '~')
  .replace(/vipulbh09@gmail\.com/g, '[email]')
  .replace(/\/private\/tmp\/claude-501\/[^\s"')]*\/scratchpad/g, '<scratchpad>')
  .replace(/\x1b\[[0-9;]*m/g, '');
const strip = s => s.replace(/<system-reminder>[\s\S]*?<\/system-reminder>/g, '').replace(/<local-command-caveat>[\s\S]*?<\/local-command-caveat>/g, '').trim();
const LIMIT = 4000;
const clip = s => (s.length > LIMIT ? s.slice(0, LIMIT) + `\n… [${s.length - LIMIT} more characters omitted]` : s);
const text = s => clip(red(strip(s)));
const deep = v => (typeof v === 'string' ? clip(red(v)) : Array.isArray(v) ? v.map(deep) : v && typeof v === 'object' ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, deep(x)])) : v);
const out = [];
let thinking = 0;
for (const l of readFileSync(process.argv[2], 'utf8').trim().split('\n').map(x => JSON.parse(x))) {
  if (l.type !== 'user' && l.type !== 'assistant') continue;
  const c = l.message?.content;
  const blocks = typeof c === 'string' ? [{ type: 'text', text: c }] : c ?? [];
  const keep = [];
  for (const b of blocks) {
    if (b.type === 'thinking' || b.type === 'redacted_thinking') { thinking++; continue; }
    if (b.type === 'text') { const t = text(b.text); if (t) keep.push({ type: 'text', text: t }); }
    else if (b.type === 'tool_use') keep.push({ type: 'tool_use', id: b.id, name: b.name, input: deep(b.input) });
    else if (b.type === 'tool_result') {
      const r = Array.isArray(b.content) ? b.content.map(x => x.text ?? '').join('\n') : String(b.content ?? '');
      keep.push({ type: 'tool_result', tool_use_id: b.tool_use_id, is_error: b.is_error ?? false, content: text(r) });
    }
  }
  if (!keep.length) continue;
  out.push(JSON.stringify({ type: l.type, uuid: l.uuid, parentUuid: l.parentUuid, timestamp: l.timestamp, message: { role: l.message.role, ...(l.message.model ? { model: l.message.model } : {}), content: keep } }));
}
writeFileSync(process.argv[3], out.join('\n') + '\n');
console.error(`${out.length} records, ${thinking} thinking blocks dropped`);
EOF
