import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { parseArgs } from 'node:util';
import { fileURLToPath } from 'node:url';
import { collectEvidence, flattenResults } from './evidence.ts';
import { ClaudeCodeCli } from './llm/ClaudeCodeCli.ts';
import { triage, type TriageOutcome } from './triage.ts';
import type { Signal } from './types.ts';

// eslint-disable-next-line no-control-regex
const stripAnsi = (s: string) => s.replace(/\x1b\[[0-9;]*m/g, '');
const repoRoot = fileURLToPath(new URL('../../', import.meta.url));

const { values } = parseArgs({
  options: {
    results: { type: 'string' },
    'docker-ps': { type: 'string' },
    diff: { type: 'string' },
    out: { type: 'string', default: 'triage-results.json' },
    model: { type: 'string', default: 'sonnet' },
    max: { type: 'string', default: '6' },
    'signals-only': { type: 'boolean', default: false },
  },
});
if (!values.results) {
  console.error('usage: node src/ci-triage.ts --results results.json [--docker-ps f] [--diff f] [--out f] [--max 6] [--signals-only]');
  process.exit(2);
}

export interface TriageEntry {
  testName: string;
  status: string;
  project?: string;
  signals: Signal[];
  outcome?: Pick<TriageOutcome, 'result' | 'guardrailNotes' | 'durationMs' | 'promptVersion'>;
  error?: string;
}
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { parseArgs } from 'node:util';
import { fileURLToPath } from 'node:url';
import { ClaudeCodeCli } from './llm/ClaudeCodeCli.ts';
import { renderMarkdown } from './report.ts';
import { triage } from './triage.ts';

const repoRoot = fileURLToPath(new URL('../../', import.meta.url));

const { values } = parseArgs({
  options: {
    test: { type: 'string' },
    log: { type: 'string' },
    diff: { type: 'string' },
    results: { type: 'string' },
    'docker-ps': { type: 'string' },
    model: { type: 'string', default: 'sonnet' },
    json: { type: 'boolean', default: false },
  },
});

if (!values.test || !values.log) {
  console.error('usage: npm run triage -- --test "<test name>" --log <file> [--diff <file>] [--results results.json] [--docker-ps file] [--model sonnet] [--json]');
  process.exit(2);
}

const outcome = await triage(
  { testName: values.test, log: readFileSync(resolve(values.log), 'utf8'), gitDiff: values.diff ? readFileSync(resolve(values.diff), 'utf8') : '' },
  new ClaudeCodeCli({ model: values.model }),
  repoRoot,
  { resultsPath: values.results && resolve(values.results), dockerPsPath: values['docker-ps'] && resolve(values['docker-ps']) },
);

console.log(values.json ? JSON.stringify(outcome.result, null, 2) : renderMarkdown(values.test, outcome));

